/**
 * Published IP ranges of mail proxies and security gateways, used by `classify`.
 *
 * The ranges live in `networks.json`, generated by `bun run refresh:networks`
 * (`scripts/refresh-networks.ts`) from the official lists cited below.
 */

import { cidrKeyRange, ipKey } from "./ip-key";
import type { IpKey } from "./ip-key";
import generated from "./networks.json";

/**
 * What a hit from the network means:
 * - `on-open`: a proxy that fetches the image when the recipient opens the email (counted);
 * - `prefetch`: a proxy or gateway that fetches it whether or not anyone opens it;
 * - `scanner`: a security gateway following links or fetching content to inspect it;
 * - `null`: no verdict, the other rules decide.
 */
export type NetworkVerdict = "on-open" | "prefetch" | "scanner" | null;

export interface PublishedNetwork {
  id: string;
  /** Names the list in event reasons. */
  name: string;
  /** The official source of the ranges. */
  url: string;
  open: NetworkVerdict;
  click: NetworkVerdict;
}

/** Checked in this order; the first list that holds the IP wins. */
export const PUBLISHED_NETWORKS: readonly PublishedNetwork[] = [
  {
    // Mail Privacy Protection loads remote content through these relays. Clicks stay with
    // the other rules: people browsing in Safari with Private Relay on use the same egress.
    click: null,
    id: "apple-private-relay",
    name: "Apple iCloud Private Relay egress list",
    open: "prefetch",
    url: "https://mask-api.icloud.com/egress-ip-ranges.csv",
  },
  {
    // Google's own services (Gmail's image proxy among them): goog.json minus the customer
    // ranges in cloud.json, as Google documents for telling its services apart.
    click: "scanner",
    id: "google-services",
    name: "Google service IP list (goog.json minus cloud.json)",
    open: "on-open",
    url: "https://www.gstatic.com/ipranges/goog.json",
  },
  {
    // Exchange Online and Exchange Online Protection, where Defender for Office 365 Safe Links
    // and attachment scanning run. Opens stay prefetch so Outlook's on-open image proxy,
    // recognised by its user agent first, is still counted.
    click: "scanner",
    id: "microsoft-exchange-online",
    name: "Microsoft 365 Exchange Online endpoint list",
    open: "prefetch",
    url: "https://endpoints.office.com/endpoints/worldwide",
  },
  {
    // Mimecast's per-region netblocks, published as SPF records under _netblocks.mimecast.com
    // and documented on its "Data Centers & URLs" page.
    click: "scanner",
    id: "mimecast",
    name: "Mimecast netblocks",
    open: "scanner",
    url: "https://mimecastsupport.zendesk.com/hc/en-us/articles/34000362728979-Administration-Data-Centers-URLs",
  },
  {
    click: "scanner",
    id: "proofpoint-essentials",
    name: "Proofpoint Essentials connection details",
    open: "scanner",
    url: "https://help.proofpoint.com/Proofpoint_Essentials/Email_Security/Administrator_Topics/000_gettingstarted/020_connectiondetails",
  },
];

/** Generated ranges: CIDR blocks per network id. */
export type NetworkRanges = Readonly<Record<string, readonly string[]>>;

export type NetworkLookup = (ip: string) => PublishedNetwork | null;

/**
 * Binary search over blocks sorted by address, IPv4 before IPv6, that do not overlap (the
 * refresh script writes them so, and a test checks the committed file). Only the blocks it
 * compares are parsed, so there is nothing to build at start-up.
 */
const contains = (cidrs: readonly string[], ip: IpKey): boolean => {
  let low = 0;
  let high = cidrs.length - 1;
  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    const range = cidrKeyRange(cidrs[middle] ?? "");
    if (range === null) {
      return false;
    }
    if (
      ip.version < range.version ||
      (ip.version === range.version && ip.key < range.start)
    ) {
      high = middle - 1;
    } else if (ip.version > range.version || ip.key > range.end) {
      low = middle + 1;
    } else {
      return true;
    }
  }
  return false;
};

/** A lookup over the given ranges (sorted as `contains` needs); networks without ranges never match. */
export const networkLookup =
  (
    ranges: NetworkRanges,
    networks: readonly PublishedNetwork[] = PUBLISHED_NETWORKS
  ): NetworkLookup =>
  (ip) => {
    const key = ipKey(ip);
    if (key === null) {
      return null;
    }
    return (
      networks.find((network) => contains(ranges[network.id] ?? [], key)) ??
      null
    );
  };

/** The lookup over the committed ranges. */
export const publishedNetworkLookup: NetworkLookup = networkLookup(
  generated.ranges
);
